WITH ranked AS (SELECT id, order_id, carrier, shipped_date, delivered_date, status FROM shipments QUALIFY ROW_NUMBER() OVER (PARTITION BY status ORDER BY shipped_date, id) = 1) SELECT DATE_TRUNC('YEAR', delivered_date) AS year_start, COUNT(*) FILTER (WHERE status = 'IN_TRANSIT') AS in_transit_rows, COUNT(DISTINCT status) AS distinct_status, COUNT(*) AS cnt, SORT_ARRAY(COLLECT_SET(carrier)) AS carrier_list FROM ranked GROUP BY year_start ORDER BY distinct_status;
